<dialog class="app-dialog" id="confirm-dialog" aria-labelledby="confirm-title"><div class="dialog-head"><span class="state-illustration"><x-icon name="shield" :size="24"/></span><button type="button" class="icon-button" data-close-dialog aria-label="Close dialog"><x-icon name="close"/></button></div><h2 id="confirm-title">Confirm action</h2><p id="confirm-description" class="muted"></p><form id="confirm-form"><x-form-field id="confirm-reason-wrap" label="Reason"><textarea name="reason" id="confirm-reason" rows="3" required placeholder="Explain the reason for this change"></textarea></x-form-field><div class="dialog-note"><x-icon name="history" :size="16"/><span>Changes are validated and recorded by the server.</span></div><div class="dialog-actions"><x-button variant="secondary" data-close-dialog>Cancel</x-button><x-button type="submit" id="confirm-submit">Confirm</x-button></div></form></dialog>
